# typed: strict
# frozen_string_literal: true

# Homebrew formula for the Superopen CLI (`so`).
#
# Generated by ishanjainn/superopen's Release / Packages workflow.
# Manual install: brew install ishanjainn/superopen/so
class So < Formula
  desc "Native code graph and coding-session observability"
  homepage "https://github.com/ishanjainn/superopen"
  version "0.6.0"
  license "Apache-2.0"

  head do
    url "https://github.com/ishanjainn/superopen.git", branch: "main"
    depends_on "go" => :build
  end

  on_macos do
    on_arm do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.6.0/so-darwin-arm64.tar.gz"
      sha256 "a3139d14f04ae1e13b59c82a934c3f4704e7ea6863d93f5c1b5c5abf5b0ddc8a"
    end
    on_intel do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.6.0/so-darwin-amd64.tar.gz"
      sha256 "ca0c251900bd54505908bd6ddf509e2e6563da684073875956b5bc260b8f9ca4"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.6.0/so-linux-arm64.tar.gz"
      sha256 "97319e3a279256a52a7341d60390dafa8531aec1339ca1cf57c9e93c55c13411"
    end
    on_intel do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.6.0/so-linux-amd64.tar.gz"
      sha256 "73dbcae270fad4f7f74ff646570c4f9ab97373e7dd862beccfc6ba2c33161a4a"
    end
  end

  resource "web" do
    url "https://github.com/ishanjainn/superopen/releases/download/cli-0.6.0/so-web.tar.gz"
    sha256 "d421229754b3d67107bc87505f2a0ccc3f7f8ad0e154ebf96528d3d9adc4ecd2"
  end

  depends_on "node"

  def install
    if build.head?
      system "go", "build", "-o", bin/"so", "./cmd/so"
      cd "web" do
        system "npm", "install", "--ignore-scripts"
        system "npm", "run", "build"
      end
      standalone = buildpath/"web/.next/standalone"
      odie "web UI standalone build missing" unless (standalone/"server.js").exist?
      static_dir = buildpath/"web/.next/static"
      if static_dir.exist?
        (standalone/".next/static").mkpath
        static_dir.children.each { |child| cp_r child, standalone/".next/static"/child.basename }
      end
      public_dir = buildpath/"web/public"
      if public_dir.exist?
        (standalone/"public").mkpath
        public_dir.children.each { |child| cp_r child, standalone/"public"/child.basename }
      end
      dst = share/"superopen/web"
      dst.mkpath
      standalone.children.each { |child| cp_r child, dst/child.basename }
    else
      bin.install Dir["so*"].first => "so"
      resource("web").stage do
        dst = share/"superopen/web"
        dst.mkpath
        Pathname(".").children.each { |child| cp_r child, dst/child.basename }
      end
    end
  end

  def caveats
    <<~EOS
      Run `so install` once to wire coding-agent hooks.
      Then in any repo: `so init` and `so dev`.
      `so dev` needs Node.js (already installed as a dependency).
    EOS
  end

  test do
    assert_match "so", shell_output("#{bin}/so --help")
  end
end
